// LSP completion item -> Monaco 补全项的纯转换逻辑。
// 只做类型导入, kind / range / snippet 常量由调用方注入, 因此可在 node 环境直接单测。

import type * as monaco from 'monaco-editor';

import type { LspCompletionItem, LspRange } from './client';

/** 由调用方 (monaco.ts) 注入的 Monaco 相关常量, 使本模块不依赖 monaco 运行时。 */
export interface CompletionConversionDeps {
  /** LSP CompletionItemKind 数值 -> Monaco 枚举值 */
  kinds: Readonly<Record<number, monaco.languages.CompletionItemKind>>;
  /** 未识别或缺失 kind 时的默认枚举值 */
  textKind: monaco.languages.CompletionItemKind;
  /** snippet 插入规则枚举值 */
  insertAsSnippet: monaco.languages.CompletionItemInsertTextRule;
  /** LSP Range -> Monaco 区间 */
  toRange: (range: LspRange) => monaco.IRange;
}

export function toCompletionItem(
  item: LspCompletionItem,
  fallbackRange: monaco.IRange,
  deps: CompletionConversionDeps
): monaco.languages.CompletionItem {
  const edit = item.textEdit;
  const isSnippet = item.insertTextFormat === 2;
  const insertText = edit && 'newText' in edit ? edit.newText : (item.insertText ?? item.label);
  const range = edit && 'range' in edit ? deps.toRange(edit.range) : fallbackRange;
  const label = item.labelDetails
    ? {
        label: item.label,
        detail: item.labelDetails.detail ?? undefined,
        description: item.labelDetails.description ?? undefined,
      }
    : item.label;
  // 文档: 兼容字符串与 MarkupContent {kind, value}, 以 markdown 形式呈现
  const rawDoc = item.documentation;
  const docValue = typeof rawDoc === 'string' ? rawDoc : rawDoc?.value;
  return {
    label,
    kind: item.kind !== undefined ? (deps.kinds[item.kind] ?? deps.textKind) : deps.textKind,
    detail: item.detail,
    documentation: docValue ? { value: docValue, isTrusted: false } : undefined,
    insertText,
    insertTextRules: isSnippet ? deps.insertAsSnippet : undefined,
    range,
    sortText: item.sortText,
  };
}
